        }
      ],
      "provenance": "extracted",
      "polarity": "proscriptive",
      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "maj7",
      "function_role": "relative-minor-reduction",
      "narrative": "For major seventh chords, Martino prescribes substituting the relative minor seventh: Cmaj7 = Am9 (relative minor). This reduction allows the player to apply the minor-based activities system directly to major seventh chords without learning a separate vocabulary. Chapter 3, p. 50.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/relative-minor-reduction"
      ],
      "source_work_id": "linear-expressions",
      "references": [
        {
          "source": "linear-expressions",
          "citation": "chapter 3 p.50"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "maj9",
      "function_role": "secondary-relative-minor-reduction",
      "narrative": "For major ninth chords, Martino prescribes optionally substituting the secondary relative minor (III chord of the major key): Cmaj9 = Em7. This provides a second substitution path when the primary relative minor (Am7) is harmonically less desirable. Chapter 3, p. 50.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/secondary-relative-minor-fallback"
      ],
      "source_work_id": "linear-expressions",
      "references": [
        {
