          "citation": "chapter 3 p.50"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "maj6",
      "function_role": "relative-minor-reduction",
      "narrative": "For major sixth chords, Martino prescribes substituting the relative minor seventh: Cmaj6 = Am7. The major sixth and its relative minor share all pitch content; the substitution is direct and requires no additional voice-leading adjustment. Chapter 3, p. 50.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/relative-minor-reduction"
      ],
      "source_work_id": "linear-expressions",
      "references": [
