        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "minor-via-perfect-fifth-reduction",
      "narrative": "For dominant seventh / ninth chords (treated as quality-equivalent: C7 = C9 = C13), Martino prescribes converting to a minor form rooted a perfect fifth above the dominant root -- e.g., G9 -> Dm6 (up a P5). This closes the three-way substitution loop among m7b5, m6, and dominant ninth. Chapter 4, p. 55.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/dominant-ninth-perfect-fifth-up-rule",
        "pat-martino:linear-expressions:harmonic-substitution-reduction/same-quality-interchange"
      ],
      "source_work_id": "linear-expressions",
      "references": [
        {
          "source": "linear-expressions",
          "citation": "chapter 4 p.55"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7alt",
      "function_role": "step-up-minor-substitution",
      "narrative": "For altered dominant chords, Martino prescribes moving up one half-step from the dominant root and playing minor -- e.g., for Gb7 altered, play G minor. This single interval-direction instruction replaces the altered chord with a minor form the activities system can handle directly. Chapter 4, p. 57.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/altered-dominant-step-up-minor-rule"
      ],
      "source_work_id": "linear-expressions",
      "references": [
        {
          "source": "linear-expressions",
          "citation": "chapter 4 p.57"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7alt",
      "function_role": "scale-choice-over-altered-dominant",
      "narrative": "For altered dominant chords, Martino prescribes melodic minor over harmonic minor as the scale of choice because only melodic minor contains the b7 -- the 'hot' note of the dominant seventh chord. Harmonic minor supplies b9, #9, b5, and #5 but omits the b7, making it insufficient for fully expressing the altered dominant sound. Chapter 4, p. 57.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/melodic-minor-preference-over-altered-dominant"
      ],
      "source_work_id": "linear-expressions",
      "references": [
        {
          "source": "linear-expressions",
          "citation": "chapter 4 p.57"
        }
      ],
      "provenance": "extracted",
      "cross_ref": [
        "dom7alt/harmonic-minor-proscription"
      ],
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7alt",
      "function_role": "harmonic-minor-avoided-over-altered-dominant",
      "narrative": "Do not substitute harmonic minor over an altered dominant as a first-choice scale: although harmonic minor yields the altered 9ths and 5ths (b9, #9, b5, #5), it lacks the b7, which is the defining tone of a dominant seventh chord. Harmonic minor is a weaker choice; melodic minor is prescribed instead. Chapter 4, p. 57.",
      "source_principle_ids": [
        "pat-martino:linear-expressions:harmonic-substitution-reduction/melodic-minor-preference-over-altered-dominant"
      ],
      "source_work_id": "linear-expressions",
      "references": [
